// Uploaded photographs are processed locally; no image-upload request is sent.
const MODEL='https://huggingface.co/Xenova/clip-vit-base-patch32/resolve/6b7c523703ae26e39be4b03774966f8571c7f523/onnx/vision_model_quantized.onnx';
const INDEX_VERSION='dd908ba9c0db';
let engine,index,previewURL='',serial=0;
async function getEngine(progress){
 if(!engine)engine=(async()=>{const ort=await import('https://cdn.jsdelivr.net/npm/onnxruntime-web@1.23.2/dist/ort.wasm.min.mjs');ort.env.wasm.numThreads=1;ort.env.wasm.wasmPaths='https://cdn.jsdelivr.net/npm/onnxruntime-web@1.23.2/dist/';let bytes,cache;
 try{cache=await caches.open('cssbuy-vip-clip-v1');const r=await cache.match(MODEL);if(r)bytes=new Uint8Array(await r.arrayBuffer())}catch{}
 if(!bytes){const r=await fetch(MODEL);if(!r.ok)throw Error('Model download failed');const reader=r.body.getReader(),parts=[];let size=0;for(;;){const x=await reader.read();if(x.done)break;parts.push(x.value);size+=x.value.length;progress(Math.min(99,Math.round(size/89117001*100)))}bytes=new Uint8Array(size);let offset=0;for(const part of parts){bytes.set(part,offset);offset+=part.length}if(cache)try{await cache.put(MODEL,new Response(bytes))}catch{}}
 progress(100);return{ort,session:await ort.InferenceSession.create(bytes,{executionProviders:['wasm'],graphOptimizationLevel:'all'})}})().catch(e=>{engine=null;throw e});return engine;
}
async function getIndex(){if(!index)index=Promise.all([fetch('/visual/index.json?v='+INDEX_VERSION).then(r=>{if(!r.ok)throw Error('Index unavailable');return r.json()}),fetch('/visual/embeddings.i8?v='+INDEX_VERSION).then(r=>{if(!r.ok)throw Error('Vectors unavailable');return r.arrayBuffer()})]).then(([meta,bytes])=>{if(bytes.byteLength!==meta.count*512)throw Error('Incomplete index');const vectors=new Int8Array(bytes),norms=new Float32Array(meta.count);for(let i=0;i<meta.count;i++){let n=0;for(let j=0;j<512;j++)n+=vectors[i*512+j]**2;norms[i]=Math.sqrt(n)}return{meta,vectors,norms}}).catch(e=>{index=null;throw e});return index}
async function embed(im,progress){try{const {ort,session}=await getEngine(progress);const canvas=document.createElement('canvas');canvas.width=canvas.height=224;const ctx=canvas.getContext('2d',{willReadFrequently:true}),side=Math.min(im.width,im.height);ctx.fillStyle='#fff';ctx.fillRect(0,0,224,224);ctx.drawImage(im,(im.width-side)/2,(im.height-side)/2,side,side,0,0,224,224);const pixels=ctx.getImageData(0,0,224,224).data,a=new Float32Array(3*224*224),mean=[.48145466,.4578275,.40821073],std=[.26862954,.26130258,.27577711];for(let c=0;c<3;c++)for(let i=0;i<224*224;i++)a[c*224*224+i]=(pixels[i*4+c]/255-mean[c])/std[c];const out=await session.run({pixel_values:new ort.Tensor('float32',a,[1,3,224,224])}),v=Float32Array.from(out.image_embeds.data);let norm=Math.sqrt(v.reduce((s,x)=>s+x*x,0));for(let i=0;i<v.length;i++)v[i]/=norm;return v}finally{im.close()}}
export function rankVisualMatches(q,{meta,vectors,norms}){const scored=[];for(let i=0;i<meta.count;i++){let s=0;for(let j=0;j<512;j++)s+=q[j]*vectors[i*512+j];scored.push({...meta.items[i],score:s/norms[i]})}scored.sort((a,b)=>b.score-a.score);if(!scored.length||scored[0].score<.52)return[];const group=c=>[1,2,3].includes(c)?'tops':String(c),votes=new Map();for(const x of scored.slice(0,8)){const k=group(x.category);votes.set(k,(votes.get(k)||0)+Math.exp((x.score-scored[0].score)*20))}const category=[...votes].sort((a,b)=>b[1]-a[1])[0][0];return scored.filter(x=>group(x.category)===category&&x.score>=.52).slice(0,120)}
let visualState={file:null,busy:false,results:[],page:1,status:'',progress:null,error:false},updateVisualUI=()=>{};
export function mountVisualSearch({root,catalog,t,card,esc}){
 const token=++serial;const state=visualState,productMap=new Map(catalog.map(p=>[p.id,p]));
 const camera='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 6h4l2-3h4l2 3h4a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2Z"/><circle cx="12" cy="13" r="4"/></svg>';
 root.innerHTML=`<section class="photo-search-workspace"><div class="photo-search-heading"><h1>${esc(t('Search by photo'))}</h1><p>${esc(t('Choose a clear photo of one item. Your photo is processed on this device.'))}</p></div><div class="photo-search-panel"><div class="photo-search-symbol">${camera}</div><img class="uploaded-preview" alt="${esc(t('Your selected photo'))}" ${previewURL?'src="'+previewURL+'"':'hidden'}><div class="photo-search-actions"><label class="photo-upload"><span>${esc(t(state.file?'Choose another photo':'Upload a product photo'))}</span><input type="file" accept="image/jpeg,image/png,image/webp" aria-label="${esc(t('Upload a product photo'))}"></label><p class="image-search-help">${esc(t('Use JPG, PNG or WebP, up to 15 MB.'))}</p></div></div><div class="image-search-state" role="status" aria-live="polite"></div><button type="button" class="visual-retry" hidden>${esc(t('Try again'))}</button></section><section class="visual-results" hidden><div class="sectionhead"><h2>${esc(t('Similar products'))}</h2><span class="visual-count"></span></div><div class="grid"></div><div class="visual-pagination"></div></section>`;
 const status=root.querySelector('.image-search-state'),grid=root.querySelector('.visual-results .grid'),preview=root.querySelector('.uploaded-preview'),count=root.querySelector('.visual-count'),input=root.querySelector('input[type=file]'),retry=root.querySelector('.visual-retry'),pager=root.querySelector('.visual-pagination'),panel=root.querySelector('.photo-search-panel'),results=root.querySelector('.visual-results');
 function redraw(){if(token!==serial||!root.isConnected)return;const rows=state.results.map(x=>productMap.get(x.id)).filter(Boolean),pages=Math.max(1,Math.ceil(rows.length/48));state.page=Math.min(state.page,pages);panel.classList.toggle('has-photo',Boolean(state.file));panel.classList.toggle('is-busy',state.busy);results.hidden=state.busy||state.error||!rows.length;status.hidden=!state.status;grid.innerHTML=rows.slice((state.page-1)*48,state.page*48).map(card).join('');count.textContent=state.file&&!state.busy?String(rows.length):'';status.textContent=t(state.status)+(state.progress!==null?' '+state.progress+'%':'');status.setAttribute('role',state.error?'alert':'status');retry.hidden=!state.error||!state.file||state.retryable===false;input.disabled=state.busy;pager.innerHTML=pages>1?`<nav class="pagination" aria-label="${esc(t('Product pages'))}"><p class="pagination-summary">${esc(t('Page {page} of {pages}').replace('{page}',state.page).replace('{pages}',pages))}</p><div class="page-numbers">${Array.from({length:pages},(_,i)=>`<button type="button" class="page-link ${state.page===i+1?'is-current':''}" data-visual-page="${i+1}" ${state.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}</div></nav>`:'';pager.querySelectorAll('[data-visual-page]').forEach(b=>b.onclick=()=>{state.page=Number(b.dataset.visualPage);redraw();root.querySelector('.visual-results').scrollIntoView({block:'start'})});}
 updateVisualUI=redraw;redraw();
 async function process(file){if(!file||state.busy)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){state.status='Use JPG, PNG or WebP, up to 15 MB.';updateVisualUI();return}state.busy=true;state.file=file;state.results=[];state.page=1;state.error=false;state.retryable=true;state.progress=null;state.status='Loading image search…';if(previewURL)URL.revokeObjectURL(previewURL);previewURL='';preview.removeAttribute('src');preview.hidden=true;root.querySelector('.photo-upload>span').textContent=t('Choose another photo');updateVisualUI();let decoded=false;try{const bitmap=await createImageBitmap(file);decoded=true;previewURL=URL.createObjectURL(file);preview.src=previewURL;preview.hidden=false;const [q,idx]=await Promise.all([embed(bitmap,n=>{if(state.progress!==n){state.status=n===100?'Matching your photo…':'Download progress';state.progress=n===100?null:n;updateVisualUI()}}),getIndex()]);state.progress=null;state.status='Matching your photo…';updateVisualUI();state.results=rankVisualMatches(q,idx);state.status=state.results.length?'':'No confident visual matches. Try a clearer photo of one item.';}catch(e){console.error('Visual search:',e.message);state.progress=null;state.status=decoded?'Image search could not load. Please try again.':'This photo could not be read. Choose another photo.';state.retryable=decoded;state.error=true;}finally{state.busy=false;updateVisualUI();}}
 input.onchange=e=>{const file=e.target.files[0];e.target.value='';process(file)};retry.onclick=()=>process(state.file);
 panel.ondragover=e=>{e.preventDefault();if(!state.busy)panel.classList.add('is-dragging')};panel.ondragleave=()=>panel.classList.remove('is-dragging');panel.ondrop=e=>{e.preventDefault();panel.classList.remove('is-dragging');process(e.dataTransfer?.files[0])};
}
